#include <stdio.h>
#include <stdlib.h>

#define MAXN 50005

int head[MAXN], to[MAXN * 2], nxt[MAXN * 2], edge_cnt;

void add_edge(int u, int v) {
    edge_cnt++;
    to[edge_cnt] = v;
    nxt[edge_cnt] = head[u];
    head[edge_cnt ? u : u] = edge_cnt;
}

int dist[MAXN];
int parent_node[MAXN];
int queue[MAXN];

void bfs(int start, int n) {
    for (int i = 1; i <= n; i++) {
        dist[i] = -1;
        parent_node[i] = 0;
    }
    int qh = 0, qt = 0;
    queue[qt++] = start;
    dist[start] = 0;

    while (qh < qt) {
        int u = queue[qh++];
        for (int e = head[u]; e; e = nxt[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent_node[v] = u;
                queue[qt++] = v;
            }
        }
    }
}

int count_at_dist(int u, int p, int d) {
    if (d == 0) return 1;
    int count = 0;
    for (int e = head[u]; e; e = nxt[e]) {
        int v = to[e];
        if (v != p) {
            count += count_at_dist(v, u, d - 1);
        }
    }
    return count;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
        add_edge(v, u);
    }

    bfs(1, n);
    int u1 = 1;
    for (int i = 1; i <= n; i++) {
        if (dist[i] > dist[u1]) {
            u1 = i;
        }
    }

    bfs(u1, n);
    int u2 = u1;
    for (int i = 1; i <= n; i++) {
        if (dist[i] > dist[u2]) {
            u2 = i;
        }
    }

    int D = dist[u2];
    static int path[MAXN];
    int curr = u2;
    for (int i = D; i >= 0; i--) {
        path[i] = curr;
        curr = parent_node[curr];
    }

    long long ways = 0;

    if (D % 2 == 0) {
        int c = path[D / 2];
        int target = D / 2;
        long long sum = 0;
        long long sum_sq = 0;

        for (int e = head[c]; e; e = nxt[e]) {
            int v = to[e];
            long long cnt = count_at_dist(v, c, target - 1);
            sum += cnt;
            sum_sq += cnt * cnt;
        }
        ways = (sum * sum - sum_sq) / 2;
    } else {
        int c1 = path[D / 2];
        int c2 = path[D / 2 + 1];
        int target = D / 2;

        long long cnt1 = count_at_dist(c1, c2, target);
        long long cnt2 = count_at_dist(c2, c1, target);
        ways = cnt1 * cnt2;
    }

    printf("%d\n", D + 1);
    printf("%lld\n", ways);

    return 0;
}
